function start(){const pd=starterStatus(selectedSuperstar),od=starterStatus(selectedOpponent);if(!pd.ready||!od.ready){alert('Both wrestlers need complete authentic starter decks before a match can begin.');return superstarSelect()}const p=SUPERSTARS[selectedSuperstar],o=SUPERSTARS[selectedOpponent];state={player:createSide('player',selectedSuperstar),cpu:createSide('cpu',selectedOpponent),control:'player',position:'Standing',pile:null,log:[],message:'The bell rings. Choose a legal page.',round:1,busy:false,hold:null,lastFinisher:null,reversalDepth:0,totalCounters:0};entrance('player');entrance('cpu');if(state.player.superKey==='angle')gainMomentum('player','Knowledge',1);if(state.cpu.superKey==='angle')gainMomentum('cpu','Knowledge',1);preloadMatchArt(state.player);preloadMatchArt(state.cpu);addLog(`${p.name} begins with 0 momentum.`);addLog(`${o.name} begins with 0 momentum.`);render()}
const side=k=>state[k],other=k=>k==='player'?'cpu':'player';
function drawTo(k,n=HAND_SIZE){const s=side(k);while(s.hand.length<n&&s.deck.length){s.hand.push(s.deck.shift());s.pagesDrawn++}}
