function beginTurn(k){drawPages(k,1);state.round++;if(state.round===20){if(state.player.superKey==='angle'){gainMomentum('player','Knowledge',1);addLog(`${state.player.name} gains 1 Knowledge on turn 20.`)}if(state.cpu.superKey==='angle'){gainMomentum('cpu','Knowledge',1);addLog(`${state.cpu.name} gains 1 Knowledge on turn 20.`)}}if(state.round%5===0){for(const x of ['player','cpu'])if(side(x).superKey==='nash'){gainMomentum(x,'Attitude',1);addLog(`${side(x).name} gains 1 Attitude at the end of the fifth turn.`)}}}
